#!/usr/bin/env bash
# This file was generated by Anthropic, Claude Opus 5.5, "Go through doc/wiki-images and
# show the final versions on the wiki pages in doc/wiki without linking each one", 2026-10-27

cd "$(git rev-parse --show-toplevel)"

REPO=$(git remote get-url origin | sed -E 's#^git@github.com:#https://github.com/#; s#\.git$##')

gallery() {
  dir="doc/wiki-images/$1"
  [ -d "$dir" ] || return
  last=""
  find "$dir" -type f | sort | while read -r f; do
    sub=$(dirname "$f")
    if [ "$sub" != "$dir" ] && [ "$sub" != "$last" ]; then
      echo; echo "### ${sub#$dir/}"
    fi
    last="$sub"
    path=$(echo "$f" | sed 's/ /%20/g')
    name=$(basename "$f")
    case "$(echo "$name" | tr 'A-Z' 'a-z')" in
      *.png|*.jpg|*.jpeg|*.gif|*.svg|*.webp) echo; echo "![$name]($REPO/raw/main/$path)" ;;
      *.pdf|*.puml) echo; echo "- [$name]($REPO/blob/main/$path)" ;;
    esac
  done
}

update_page() {
  page="doc/wiki/$1"; shift
  tmp=$(mktemp)
  for folder in "$@"; do gallery "$folder"; done > "$tmp"
  grep -q '<!-- images:start -->' "$page" || printf '\n<!-- images:start -->\n<!-- images:end -->\n' >> "$page"
  awk -v tmp="$tmp" '
    /<!-- images:start -->/ { print; while ((getline line < tmp) > 0) print line; skip=1; next }
    /<!-- images:end -->/   { skip=0 }
    !skip { print }
  ' "$page" > "$page.new" && mv "$page.new" "$page"
  rm -f "$tmp"
}

# Which folders go on which page
update_page CRC.md   "CRC-Cards/final version"
update_page Figma.md "Figma"
update_page UML.md   "UML"

echo "Wiki pages updated."
